from __future__ import annotations

import argparse
import json
from collections.abc import Iterable
from pathlib import Path
from typing import Any


def read_events(path: Path) -> list[dict[str, Any]]:
    events: list[dict[str, Any]] = []
    with path.open(encoding="utf-8") as source:
        for line in source:
            if line.strip():
                events.append(json.loads(line))
    return events


def compact_events(events: Iterable[dict[str, Any]]) -> list[dict[str, Any]]:
    by_id: dict[str, dict[str, Any]] = {}
    order: list[str] = []
    for event in events:
        event_id = str(event["id"])
        if event_id not in by_id:
            order.append(event_id)
        by_id.setdefault(event_id, event)
    return [
        by_id[event_id]
        for event_id in sorted(order)
        if by_id[event_id].get("op") != "delete"
    ]


def write_events(path: Path, events: Iterable[dict[str, Any]]) -> None:
    with path.open("w", encoding="utf-8") as destination:
        for event in events:
            destination.write(
                json.dumps(event, sort_keys=True, separators=(",", ":")) + "\n"
            )


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("input", type=Path)
    parser.add_argument("output", type=Path)
    args = parser.parse_args()
    write_events(args.output, compact_events(read_events(args.input)))


if __name__ == "__main__":
    main()

from __future__ import annotations

import unittest

from ledger import compact_events


class CompactEventsTests(unittest.TestCase):
    def test_latest_event_wins_and_final_order_is_stable(self) -> None:
        events = [
            {"id": "b", "op": "upsert", "payload": {"value": 1}},
            {"id": "a", "op": "upsert", "payload": {"value": 2}},
            {"id": "b", "op": "upsert", "payload": {"value": 3}},
        ]
        self.assertEqual(
            compact_events(events),
            [
                {"id": "a", "op": "upsert", "payload": {"value": 2}},
                {"id": "b", "op": "upsert", "payload": {"value": 3}},
            ],
        )

    def test_delete_tombstone_removes_latest_record(self) -> None:
        events = [
            {"id": "gone", "op": "upsert", "payload": {}},
            {"id": "keep", "op": "upsert", "payload": {"ok": True}},
            {"id": "gone", "op": "delete"},
        ]
        self.assertEqual(
            compact_events(events),
            [{"id": "keep", "op": "upsert", "payload": {"ok": True}}],
        )


if __name__ == "__main__":
    unittest.main()

from __future__ import annotations

import argparse
import json
from collections.abc import Iterable
from pathlib import Path
from typing import Any


def read_events(path: Path) -> list[dict[str, Any]]:
    events: list[dict[str, Any]] = []
    with path.open(encoding="utf-8") as source:
        for line_number, line in enumerate(source, start=1):
            if not line.strip():
                continue
            try:
                event = json.loads(line)
            except json.JSONDecodeError as error:
                raise ValueError(f"line {line_number}: invalid JSON") from error
            if not isinstance(event, dict):
                raise ValueError(f"line {line_number}: event must be an object")
            event_id = event.get("id")
            operation = event.get("op")
            if not isinstance(event_id, str) or not event_id:
                raise ValueError(f"line {line_number}: id must be a non-empty string")
            if operation not in {"upsert", "delete"}:
                raise ValueError(f"line {line_number}: unsupported operation")
            if operation == "upsert" and not isinstance(event.get("payload"), dict):
                raise ValueError(f"line {line_number}: upsert payload must be an object")
            events.append(event)
    return events


def compact_events(events: Iterable[dict[str, Any]]) -> list[dict[str, Any]]:
    latest: dict[str, tuple[int, dict[str, Any]]] = {}
    for index, event in enumerate(events):
        latest[event["id"]] = (index, event)
    ordered = sorted(latest.values(), key=lambda entry: entry[0])
    return [event for _, event in ordered if event["op"] != "delete"]


def write_events(path: Path, events: Iterable[dict[str, Any]]) -> None:
    with path.open("w", encoding="utf-8") as destination:
        for event in events:
            destination.write(
                json.dumps(event, sort_keys=True, separators=(",", ":")) + "\n"
            )


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("input", type=Path)
    parser.add_argument("output", type=Path)
    args = parser.parse_args()
    write_events(args.output, compact_events(read_events(args.input)))


if __name__ == "__main__":
    main()

from __future__ import annotations

import unittest

from release_plan import deployment_stages


class DeploymentStagesTests(unittest.TestCase):
    def test_changed_dependency_redeploys_transitive_dependents(self) -> None:
        graph = {
            "db": [],
            "api": ["db"],
            "worker": ["db"],
            "web": ["api"],
        }
        self.assertEqual(
            deployment_stages(graph, ["db"]),
            [["db"], ["api", "worker"], ["web"]],
        )

    def test_unchanged_prerequisite_is_not_redeployed(self) -> None:
        graph = {"db": [], "api": ["db"], "web": ["api"]}
        self.assertEqual(deployment_stages(graph, ["api"]), [["api"], ["web"]])


if __name__ == "__main__":
    unittest.main()

from __future__ import annotations

import argparse
import json
from collections.abc import Iterable, Mapping, Sequence
from pathlib import Path


def _validated_graph(graph: Mapping[str, Sequence[str]]) -> dict[str, set[str]]:
    if not isinstance(graph, Mapping) or not all(isinstance(name, str) for name in graph):
        raise ValueError("graph must map service names to dependencies")
    normalized: dict[str, set[str]] = {}
    for name, dependencies in graph.items():
        if isinstance(dependencies, str) or not isinstance(dependencies, Sequence):
            raise ValueError(f"dependencies for {name} must be a sequence")
        if not all(isinstance(dependency, str) for dependency in dependencies):
            raise ValueError(f"dependencies for {name} must be service names")
        normalized[name] = set(dependencies)
    unknown = {dependency for dependencies in normalized.values() for dependency in dependencies} - normalized.keys()
    if unknown:
        raise ValueError(f"unknown dependency: {sorted(unknown)}")
    remaining = {name: set(dependencies) for name, dependencies in normalized.items()}
    while remaining:
        ready = {name for name, dependencies in remaining.items() if not (dependencies & remaining.keys())}
        if not ready:
            raise ValueError("dependency cycle detected")
        for name in ready:
            remaining.pop(name)
    return normalized


def deployment_stages(
    graph: Mapping[str, Sequence[str]],
    changed: Iterable[str],
) -> list[list[str]]:
    normalized = _validated_graph(graph)
    selected = set(changed)
    unknown_changed = selected - normalized.keys()
    if unknown_changed:
        raise ValueError(f"unknown changed service: {sorted(unknown_changed)}")
    reverse: dict[str, set[str]] = {name: set() for name in normalized}
    for name, dependencies in normalized.items():
        for dependency in dependencies:
            reverse[dependency].add(name)
    impacted = set(selected)
    frontier = list(selected)
    while frontier:
        dependency = frontier.pop()
        for dependent in reverse[dependency]:
            if dependent not in impacted:
                impacted.add(dependent)
                frontier.append(dependent)
    stages: list[list[str]] = []
    remaining = set(impacted)
    while remaining:
        ready = sorted(name for name in remaining if not (normalized[name] & remaining))
        if not ready:
            raise ValueError("dependency cycle detected")
        stages.append(ready)
        remaining.difference_update(ready)
    return stages


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("graph", type=Path)
    parser.add_argument("changed", nargs="+")
    args = parser.parse_args()
    graph = json.loads(args.graph.read_text(encoding="utf-8"))
    print(
        json.dumps(
            {"stages": deployment_stages(graph, args.changed)},
            separators=(",", ":"),
        )
    )


if __name__ == "__main__":
    main()

from __future__ import annotations

import asyncio
from collections.abc import Awaitable, Callable, Iterable
from typing import TypeVar

Input = TypeVar("Input")
Output = TypeVar("Output")


async def run_bounded(
    items: Iterable[Input],
    worker: Callable[[Input], Awaitable[Output]],
    limit: int,
) -> list[Output]:
    if isinstance(limit, bool) or not isinstance(limit, int) or limit < 1:
        raise ValueError("limit must be a positive integer")
    materialized = list(items)
    if not materialized:
        return []
    semaphore = asyncio.Semaphore(limit)

    async def run_one(item: Input) -> Output:
        async with semaphore:
            return await worker(item)

    tasks = [asyncio.create_task(run_one(item)) for item in materialized]
    try:
        return list(await asyncio.gather(*tasks))
    except BaseException:
        for task in tasks:
            if not task.done():
                task.cancel()
        await asyncio.gather(*tasks, return_exceptions=True)
        raise
